package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,qualifiers="w360dp-h800dp-mdpi",shadows={ReferenceDesign5150Test.LocalStorage.class}) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class FlashTheme5170Test {
 ReferenceDesign5150Test f;MainActivity a;ServiceController<QuickSearchService> driver;QuickSearchService s;
 @Before public void before()throws Exception{f=new ReferenceDesign5150Test();f.before();a=f.a;}
 @After public void after()throws Exception{if(driver!=null)driver.destroy();f.after();}
 void service(){driver=Robolectric.buildService(QuickSearchService.class).create();s=driver.get();s.bubble();shadowOf(Looper.getMainLooper()).idle();}
 void clock(long millis){shadowOf(Looper.getMainLooper()).idleFor(millis,TimeUnit.MILLISECONDS);}
 void configure(int corner){a.prefs.edit().putBoolean("flash_auto_hide",true).putInt("flash_idle_seconds",3).putInt("flash_corner",corner).apply();service();}
 void event(int action,float x,float y){long t=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(t,t,action,x,y,0);s.window.dispatchTouchEvent(e);e.recycle();}
 @Test public void flashCanShrinkBelowEightyPercentWithoutLosingItsTouchTarget(){IconSizing.set(a,"flash_button_size",-3);SizeControl c=new SizeControl(a,"Flash","flash_button_size",n->{});assertEquals(16,IconSizing.bubbleVisual(IconSizing.bubble(a)));assertEquals(44,IconSizing.bubbleTouch(-3));assertFalse(c.minus.isEnabled());assertEquals("31%",c.value.getText().toString());for(int i=0;i<5;i++)c.plus.performClick();assertEquals(2,IconSizing.bubble(a));assertFalse(c.plus.isEnabled());}
 @Test public void normalBubbleDoesNotHideUnlessEnabled(){service();clock(6000);assertFalse(s.tucked);assertTrue(s.params.x>=0);}
 @Test public void idleCornerShowsExactlyHalfAndKeepsTheSavedAnchor(){a.prefs.edit().putInt("float_x",80).putInt("float_y",200).apply();configure(1);clock(3100);assertTrue(s.tucked);assertEquals(-s.params.width/2,s.params.x);assertEquals(30,s.params.y);assertEquals(80,a.prefs.getInt("float_x",-1));assertTrue((s.params.flags&WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS)!=0);}
 @Test public void allFourCornersUseTheRightScreenEdges(){configure(1);for(int corner=1;corner<=4;corner++){a.prefs.edit().putInt("flash_corner",corner).apply();shadowOf(Looper.getMainLooper()).idle();clock(3100);assertTrue(s.tucked);assertEquals(corner==2||corner==4?360-s.params.width/2:-s.params.width/2,s.params.x);assertEquals(corner<=2?30:800-s.params.height-30,s.params.y);}}
 @Test public void touchingTheVisibleHalfOpensSearchImmediately(){configure(2);clock(3100);event(MotionEvent.ACTION_DOWN,10,20);assertFalse(s.tucked);event(MotionEvent.ACTION_UP,10,20);assertTrue(s.expanded);assertTrue(s.window instanceof FlashPanelView);}
 @Test public void heldDragDoesNotHideAndRestartsTheIdleTimerOnRelease(){configure(0);clock(2000);event(MotionEvent.ACTION_DOWN,25,25);event(MotionEvent.ACTION_MOVE,50,55);clock(3500);assertFalse(s.tucked);event(MotionEvent.ACTION_UP,50,55);assertFalse(s.tucked);clock(3100);assertTrue(s.tucked);}
 @Test public void transparencyAffectsOnlyTheBubbleAndNotTheSearchPanel(){a.prefs.edit().putInt("flash_opacity",35).apply();service();assertEquals(.35f,s.params.alpha,.001f);s.expand();assertEquals(1f,s.params.alpha,.001f);s.collapse(null);assertEquals(.35f,s.params.alpha,.001f);}
 @Test public void rotationRestoresTheBubbleBeforeReschedulingItsRecollection(){configure(1);clock(3100);s.onConfigurationChanged(new Configuration(a.getResources().getConfiguration()));assertFalse(s.tucked);assertTrue(s.params.x>=6);clock(3100);assertTrue(s.tucked);}
 @Test public void customThemesKeepContrastForBrightDarkAndMidToneBackgrounds(){for(int bg:new int[]{Color.WHITE,Color.BLACK,0xff777777,0xff757575,0xff00ff00,0xffff00ff,0xff0369a1})for(int accent:new int[]{Color.YELLOW,Color.CYAN,Color.WHITE,Color.BLACK,0xff8234ee}){AppPalette p=new AppPalette(accent,bg);assertTrue(Integer.toHexString(bg),AppPalette.contrast(p.ink,p.bg)>=4.5);assertTrue(AppPalette.contrast(p.ink,p.surface)>=4.5);assertTrue("accent "+Integer.toHexString(bg),AppPalette.contrast(p.accent,p.bg)>=4.5);assertTrue(AppPalette.contrast(p.accent,p.surface)>=4.5);assertTrue(AppPalette.contrast(p.onAccent,p.accent)>=4.5);assertTrue(AppPalette.contrast(p.muted,p.bg)>=4.5);assertTrue(AppPalette.contrast(p.heroStart,Color.WHITE)>=4.5);assertTrue(AppPalette.contrast(p.heroEnd,Color.WHITE)>=4.5);}}
 @Test public void expandedColorListAndCustomThemeApplyToTheLiveBubble(){assertEquals(17,AppPalette.NAMES.length);service();View previous=s.window;a.prefs.edit().putInt("theme_custom_accent",0xff008080).putInt("theme_custom_background",0xff101820).putString("theme","Personalizado").apply();shadowOf(Looper.getMainLooper()).idle();assertNotSame(previous,s.window);assertFalse(AppPalette.of(a).light);assertEquals(AppPalette.of(a).onAccent,((Icons)((FlashBubbleView)s.window).circle.getChildAt(0)).color);a.prefs.edit().clear().apply();shadowOf(Looper.getMainLooper()).idle();assertNotNull(s.window);}
 @Test public void flashAdvancedSettingsHaveNativeTransparencyAndCornerControls()throws Exception{FlashSettings.show(a);UiDialog d=(UiDialog)ShadowDialog.getLatestDialog();String labels=BooksToolsTest.labels(d.root);assertTrue(labels.contains("Transparência"));assertTrue(labels.contains("Recolher quando"));assertTrue(labels.contains("Posição de recolha"));f.capture(d.root,"flash-ajustes-5170",336,650);d.dismiss();}
 @Test public void customThemeEditorAndHomeHaveNativePreviews()throws Exception{a.prefs.edit().putString("theme","Personalizado").putInt("theme_custom_accent",0xff087f81).putInt("theme_custom_background",0xffedf8f6).apply();a.render();f.drain();f.capture(a.shell,"tema-personalizado-5170",360,800);ThemeSettings.custom(a);UiDialog d=(UiDialog)ShadowDialog.getLatestDialog();assertTrue(BooksToolsTest.labels(d.root).contains("Cor de destaque"));assertTrue(BooksToolsTest.labels(d.root).contains("Cor do fundo"));f.capture(d.root,"cores-personalizadas-5170",336,570);d.dismiss();}
 @Test public void archiveMenuOffersExtractionAndCompression(){Catalog.Entry e=new Catalog.Entry();e.name="livros.zip";e.category="Arquivos";e.uri="content://example/books";e.mime="application/zip";a.fileMenu(e);UiPanel d=UiPanel.open.get(a).iterator().next();String labels=BooksToolsTest.labels(d.root);assertTrue(labels.contains("Extrair / descompactar"));assertTrue(labels.contains("Compactar em ZIP"));}
 @Test public void archiveActionCreatesAndExtractsFilesThroughTheActivityWorker()throws Exception{java.io.File root=android.os.Environment.getExternalStorageDirectory(),folder=new java.io.File(root,"archive-ui-"+java.util.UUID.randomUUID());assertTrue(folder.mkdir());java.io.File input=new java.io.File(folder,"matéria.txt");java.nio.file.Files.write(input.toPath(),"Conteúdo real".getBytes("UTF-8"));Catalog.Entry entry=StorageAccess.entry(input,root);ArchiveUi.run(a,false,java.util.Collections.singletonList(entry),folder,"teste.zip",new char[0]);a.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();assertTrue(new java.io.File(folder,"teste.zip").isFile());assertFalse(a.busy);UiDialog.dismissAll(a);Catalog.Entry zip=StorageAccess.entry(new java.io.File(folder,"teste.zip"),root);ArchiveUi.run(a,true,java.util.Collections.singletonList(zip),folder,"extraido",new char[0]);a.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();assertEquals("Conteúdo real",new String(java.nio.file.Files.readAllBytes(new java.io.File(folder,"extraido/matéria.txt").toPath()),"UTF-8"));assertTrue(input.isFile());assertFalse(a.busy);ArchiveFiles.remove(folder);}
 @Test public void openingANewAppIntentCanReachFlashSettings()throws Exception{a.onNewIntent(new Intent(a,MainActivity.class).putExtra(FlashSettings.OPEN,true));clock(400);UiDialog d=(UiDialog)ShadowDialog.getLatestDialog();assertTrue(d.isShowing());assertTrue(BooksToolsTest.labels(d.root).contains("Transparência"));}

}
